+        // a prompt the coordinator answers) must find this pane
+        // listening.
+        _statusWatch = lanes
+            .watchServer(bookmark.id)
+            .listen(
+              (status) {
+                if (_disposed || attempt != _bindAttempt) return;
+                _connectionStatus = status;
+                notifyListeners();
+              },
+              onError: (Object error, StackTrace stackTrace) {
+                if (_disposed || attempt != _bindAttempt) return;
