+    }
+  }
+
+  /// Navigates to the parent folder; the root is its own parent (no-op).
+  void goUp() {
+    final current = _location;
+    if (current == null) return;
+    final parent = paneParentPath(current.path);
+    if (parent == current.path) return;
+    navigate(parent);
+  }
